def transform(grid):
    h, w = len(grid), len(grid[0])

    # The divider is the uniform column separating two equal-width panels.
    divider = next(
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
        and c * 2 == w - 1
    )
    left = [row[:divider] for row in grid]
    right = [row[divider + 1:] for row in grid]

    shared = set(v for row in left for v in row) & set(v for row in right for v in row)
    background = next(iter(shared))

    return [
        [3 if left[r][c] == background and right[r][c] == background else background
         for c in range(divider)]
        for r in range(h)
    ]
